import {PATRONS,PROFESSIONS,ROOMS,SPELLS,RITUAL} from './life-data.js';
import {PLACES,QUESTS,ITEMS} from './world.js';
import {quantity,routeTo} from './engine.js';
const place=id=>PLACES.find(p=>p.id===id);
export function templePanel(p,{state:s,button:b,esc,file}){
 const here=s.location===p.temple,used=s.flags['prayed:'+p.id+':'+Math.floor(s.tick/24)];
 return `<section class="life-card"><img src="${file(p.art)}" alt="Reused campaign scene illustrating ${esc(p.name)}" loading="lazy"><div class="life-copy"><span class="eyebrow">Moonveil homebrew patron · ${esc(place(p.temple).name)}</span><h3>${esc(p.name)}</h3><p>${esc(p.theme)}</p><blockquote>“${esc(p.line)}”<small>— ${esc(p.keeper)}</small></blockquote><p>${esc(p.tenet)}</p><p class="muted">Devotion: ${s.devotion?.[p.id]||0} · Offerings grant advantage on your next attack; they do not stack. Once per temple per world day.</p><div class="secondary-actions">${here?b(used?'Offering made today':'Offer a candle · 3 gold','temple-service',`data-patron="${p.id}" data-service="pray" ${used||s.hero.gold<3?'disabled':''}`)+b('Receive healing · 5 gold','temple-service',`data-patron="${p.id}" data-service="heal" ${s.hero.gold<5||s.hero.hp===s.hero.maxHp?'disabled':''}`):b('Show temple route','inspect-place',`data-place="${p.temple}"`)}</div></div></section>`;
}
export function cryptView({state:s,button:b,esc,file}){
 const room=ROOMS.find(r=>r.id===(s.flags.cryptRoom||'vestibule')),active=s.battle?.status==='active'||s.loot;
 return `<section class="section-divider"><span class="eyebrow">Dungeon exploration · four connected chambers</span><h2>${room.name}</h2><div class="dungeon-map" role="group" aria-label="Crypt room map"><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M20 50 L48 22 L80 50 L48 78 Z"/></svg>${ROOMS.map(r=>`<div class="dungeon-room ${r.id===room.id?'current':''}" style="left:${r.x}%;top:${r.y}%">${r.name}${r.id===room.id?'<small>You are here</small>':''}</div>`).join('')}</div><div class="life-card"><img src="${file(room.art)}" alt="Reused campaign illustration for ${room.name}"><div class="life-copy"><p>${room.id==='vault'&&['return','complete'].includes(s.quests['quietus-seal']?.phase)?'The echo and its bailiff are at rest. The reliquary stands quiet; the recovered seal is recorded in your inventory.':room.text}</p><p class="muted">Testament: ${s.flags.testamentRead?'read':'not found'} · Reliquary: ${s.flags.reliquaryOpen?'open':'sealed'} · Offering: ${s.flags.ossuaryLoot?'collected':'unclaimed'}</p>${b(room.interaction,'room-interact',active?'disabled':'','primary')}<div class="secondary-actions">${room.neighbors.map(id=>b('Enter '+ROOMS.find(r=>r.id===id).name,'room-move',`data-room="${id}" ${active?'disabled':''}`)).join('')}</div>${room.id==='vault'&&s.flags.reliquaryOpen&&s.quests['quietus-seal']?.phase==='accepted'?b('Confront the lichbound echo','engage',active?'disabled':'','primary'):''}<p class="muted">The room map controls connected exploration. The combat grid separately shows the exact blocking walls. Images illustrate chambers; they do not define collision.</p></div></div></section>`;
}
export function lifeView(ctx){const {state:s,button:b,esc,file}=ctx,p=PROFESSIONS.find(p=>p.id===s.profession?.id);
 return `<div class="view-header"><span class="eyebrow">Your living-world journal</span><h2>Work. Wonder. Leave a light.</h2><p>Quests, professions, temples, devotion and spell rules in one place. These additions use Moonveil homebrew lore and mechanics.</p></div><div class="sheet-links"><a href="#quest-sheet">Quest journal</a><a href="#profession-sheet">Professions</a><a href="#devotion-sheet">Deities & temples</a><a href="#ritual-sheet">Rituals & ascension</a><a href="#spell-sheet">Spells & rules</a>${b('Character sheet','view','data-view="character"')}${b('Inventory sheet','view','data-view="inventory"')}${b('Export all character progress','export')}</div>
 <section id="quest-sheet" class="section-divider"><span class="eyebrow">Every implemented adventure</span><h2>Quest journal</h2><p class="muted">${QUESTS.length+PROFESSIONS.length+1} playable quest/commission entries. Rewards below are one-time. This is the implemented journal, not every quest from every source archive.</p>${QUESTS.map(q=>{const phase=s.quests[q.id]?.phase||'not accepted',target=phase==='return'?q.giver:q.site,route=routeTo(s,target);return `<article class="journal-row"><div><span class="pill">${phase}</span><h3>${q.name}</h3><p>${q.summary}</p><p class="muted">Giver: ${place(q.giver).speaker} · ${q.reward} gold / ${q.xp} XP</p><small>${phase==='complete'?'Complete and saved.':phase==='not accepted'?'Begin at '+place(q.giver).name:route?.length>1?'Next road: '+place(route[1]).name:'You are at the objective.'}</small></div>${b('Show route','inspect-place',`data-place="${phase==='not accepted'?q.giver:target}"`)}</article>`;}).join('')}
 <article class="journal-row"><div><span class="pill">${s.flags.pilgrimageComplete?'complete':s.flags.pilgrimageAccepted?'accepted':'not accepted'}</span><h3>Three Lights, One Road</h3><p>Keeper Ilyra asks you to visit all three temples, speak to their keepers, and make an offering. Return to the Nexus to share what you learned.</p><p>${PATRONS.map(p=>(s.flags['pilgrim:'+p.id]?'✓ ':'○ ')+p.name).join(' · ')}</p><small>20 gold / 25 XP · Temple offerings cost 3 gold each.</small></div>${s.flags.pilgrimageComplete?'':s.location==='nexus'?s.flags.pilgrimageAccepted?b('Complete pilgrimage','pilgrim-claim',PATRONS.every(p=>s.flags['pilgrim:'+p.id])?'':'disabled'):b('Accept pilgrimage','pilgrim-accept'):b('Show Nexus route','inspect-place','data-place="nexus"')}</article>
 ${PROFESSIONS.map(p=>`<article class="journal-row"><div><span class="pill">${s.flags['order:'+p.id]?.phase||'not accepted'}</span><h3>${p.order}</h3><p>Train with ${p.mentor}, accept this commission, craft a fresh ${ITEMS.find(i=>i.id===p.product).name}, then deliver it here.</p><small>18 gold / 15 XP · ${place(p.hub).name} · Crafting and delivery consume materials/product.</small></div>${b('Show workshop route','inspect-place',`data-place="${p.hub}"`)}</article>`).join('')}</section>
 <section id="profession-sheet" class="section-divider"><span class="eyebrow">Profession sheet</span><h2>${p?p.name+' · '+s.profession.xp+' XP':'Choose your craft.'}</h2><p>A profession is separate from your combat calling. Changing professions starts its training XP at zero; completed commissions remain recorded. Collect workshop supplies once per world day.</p><div class="life-grid">${PROFESSIONS.map(p=>{const here=s.location===p.hub,trained=s.profession?.id===p.id,order=s.flags['order:'+p.id],crafted=(s.flags['crafted:'+p.id]||0)>(order?.craftedBefore??Infinity),collected=s.flags['gather:'+p.id+':'+Math.floor(s.tick/24)];return `<article class="life-card"><img src="${file(p.art)}" alt="Reused campaign workshop scene for ${p.name}" loading="lazy"><div class="life-copy"><span class="eyebrow">${place(p.hub).name}</span><h3>${p.name}</h3><blockquote>“${p.line}”<small>— ${p.mentor}</small></blockquote><p>Recipe: 2 ${ITEMS.find(i=>i.id===p.material).name} + ${p.cost} gold → ${ITEMS.find(i=>i.id===p.product).name}</p><p class="muted">Materials held: ${quantity(s,p.material)} · Products crafted: ${s.flags['crafted:'+p.id]||0} · +10 profession XP per craft.</p><div class="secondary-actions">${!here?b('Show workshop route','inspect-place',`data-place="${p.hub}"`):!trained?b(s.profession?'Change profession':'Train for free','life-train',`data-profession="${p.id}"`):b(collected?'Supplies collected today':'Collect daily supplies','life-gather',collected?'disabled':'')+b('Craft · '+p.cost+' gold','life-craft',quantity(s,p.material)<2||s.hero.gold<p.cost?'disabled':'')+(!order?b('Accept commission','life-order',`data-profession="${p.id}"`):order.phase==='complete'?'<span class="pill">Commission complete</span>':b('Deliver crafted product','life-deliver',`data-profession="${p.id}" ${crafted&&quantity(s,p.product)>0?'':'disabled'}`))}</div></div></article>`;}).join('')}</div></section>
 <section id="devotion-sheet" class="section-divider"><span class="eyebrow">Devotion sheet · new campaign traditions</span><h2>Keepers of the small lights.</h2><p>These three patrons are new homebrew additions. Existing archived patrons, including Vaelthara, have not been replaced or rewritten. Temple illustrations are reused campaign scenes, not deity portraits.</p><div class="life-grid">${PATRONS.map(p=>templePanel(p,ctx)).join('')}</div></section>
 ${ritualView(ctx)}<section id="spell-sheet" class="section-divider"><span class="eyebrow">Spell sheet & interaction rules</span><h2>Know what your choices do.</h2><p>Focus: ${s.hero.slots}/${s.hero.maxSlots}. Rest safely to restore it. These two spells are homebrew additions, separate from the SRD reference library.</p>${SPELLS.map(sp=>`<article class="journal-row"><div><h3>${sp.name}</h3><p>${sp.text}</p></div></article>`).join('')}<div class="notice">Shatter sequence: select an enemy → cast Frost Sigil → end your turn → cast Storm Arc on that same enemy. The frost mark persists until consumed. Each spell takes your one action and costs one focus. Total combo: 1d4 + 1d6 + 1d4 damage across two turns. Marks do not stack.</div><div class="rules-grid"><article><h3>Travel & exploration</h3><p>Only connected roads and adjacent crypt rooms can be entered. Previewing a location never moves you. Exploration grants its discovery XP once per place. Collect encounter loot before leaving.</p></article><article><h3>Walls & turns</h3><p>Movement follows open orthogonal squares, up to 6 squares per turn. Units and walls block passage; walls block ranged line of sight. Melee reaches adjacent squares, including diagonals. Enemies move up to 4 squares and attack when adjacent.</p></article><article><h3>Actions & recovery</h3><p>One attack, spell, potion or brace per turn. Orison’s shield spends companion charge separately. Brace adds 2 AC for the next enemy turn. Healing potions recover 2d4 + 2 HP. Retreat returns you to the Nexus with half health and retains accepted quests.</p></article><article><h3>World time & consequences</h3><p>A world day is 24 action pulses. Workshop supplies and temple offerings reset by world day, not your computer clock. Services spend the displayed gold. Walls are implemented; fire, water, weather damage and other environmental hazards are not yet simulated.</p></article></div></section>`;
}

function ritualView({state:s,button:b}){const ready=s.flags.pilgrimageComplete&&s.quests['quietus-seal']?.phase==='complete',here=s.location==='nexus',hasScroll=quantity(s,'concordance-scroll')>0,step=s.flags.ritualStep||0;
return `<section id="ritual-sheet" class="section-divider"><span class="eyebrow">Ritual & ascension sheet · Moonveil homebrew</span><h2>${RITUAL.name}</h2><p>This first ascension grants the campaign title Waybound Ascendant and +1 maximum focus. It does not make your character an official D&D deity. Further divine quest chains remain under development.</p><ol class="ritual-requirements"><li>${s.flags.pilgrimageComplete?'✓':'○'} Complete Three Lights, One Road: offer a candle in each temple and return to Ilyra.</li><li>${s.quests['quietus-seal']?.phase==='complete'?'✓':'○'} Complete Let the Dead Be Still and return the Quietus Seal.</li><li>${hasScroll||s.flags.ascended?'✓':'○'} Inscribe a Scroll of Three Lights at the Nexus: 2 Star Ink Pigments + 8 gold. Cartographers collect pigments there.</li><li>${s.flags.ascended?'✓':'○'} Trace the five nodes in order at the Nexus while carrying the scroll and 15 gold.</li></ol><p class="muted">Sequence: Remembrance → Witness → Mercy → Resolve → Return. A wrong node resets the trace without consuming the scroll or gold. Completion consumes one scroll and 15 gold, once only.</p><div class="ritual-diagram" role="group" aria-label="Interactive five-node ascension diagram"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="37"/><path d="M50 12 L74 82 L13 38 L87 38 L26 82 Z"/></svg>${RITUAL.nodes.map(n=>b(n.name,'ritual-node',`data-node="${n.id}" style="left:${n.x}%;top:${n.y}%" ${!ready||!here||!hasScroll||s.flags.ascended||s.hero.gold<15?'disabled':''}`,'ritual-node '+(RITUAL.sequence.slice(0,step).includes(n.id)?'traced':''))).join('')}<div class="ritual-center">${s.flags.ascended?'ASCENDED':step+' / 5'}<small>${s.flags.ascended?'Waybound Ascendant':'The Concordance'}</small></div></div><div class="secondary-actions">${b('Inscribe ritual scroll · 8 gold','inscribe-scroll',!ready||!here||hasScroll||s.flags.ascended||quantity(s,'star-dust')<2||s.hero.gold<8?'disabled':'')}${!here?b('Show Nexus route','inspect-place','data-place="nexus"'):''}</div><p>Scrolls held: ${quantity(s,'concordance-scroll')} · Star Ink Pigments: ${quantity(s,'star-dust')} · Gold: ${s.hero.gold} · Rank: ${s.flags.ascended?'Waybound Ascendant':'Traveler'}</p></section>`;}
